    coverage:creator?`Charles creator ${range(creator.coverage)} UTC · final day partial; historical company reference is separate`:content.coverage,asOf:source('content').asOf||content.snapshotAt,status:source('content').status||content.status||'Import needed',
    activity:contentActivity,responses:contentResponses,outcomes:[glanceMetric(null,'Attributed qualified leads')],
