  html+=waalaxySheetSubset(w)+waalaxySelectedExportReview(w);
  html+=heading('Historical prospect reference','People with lifetime flags remain distinct from period event counts.');
  html+=kpis([[num(count('uniqueProspects','prospects','sourceRows','totalProspects','total')),'Historical prospect records','Charles-only retained person snapshot'],[num(count('connectionRequestedProspects','invitationSent','invitationsSent','invitationSentFlags')),'Historical invitation flags','People, not current period sends'],[num(count('messageRecipients','messageSent','messagesSent','messageSentFlags')),'Historical message recipients','People, not a count of every message'],[num(count('replyingProspects','replied','replies','replyFlags')),'Historical replying prospects','People, not current period replies']]);
