  html+=table('content-creator-top','Current creator top-post sample',a.topPosts||[],[{key:'title',label:'Post',render:(v,r)=>link(r.url,v)},{key:'impressions',label:'Window impressions',render:num},{key:'engagements',label:'Window engagements',render:num}],`${num(a.topPosts?.length||0)} visible ranked posts measured in ${range(cov)} UTC. These are source-window metrics, not lifetime totals. Publication dates and a complete current post register were not supplied. This sample does not follow the reporting-period filter.`);
