function calendarReview(){
  const m=S.data.meetings;if(!m?.events?.length)return recordingEvidenceReview();
  const generic=m.events.filter(e=>e.commercialClassification!=='excluded_interview_type');
  const chains=new Map();for(const e of generic){if(!chains.has(e.bookingChainId))chains.set(e.bookingChainId,e);}
  const covered=S.end>=m.coverage.start&&S.start<m.coverage.end,partial=covered&&(S.start<m.coverage.start||S.end>=m.coverage.end);
  const creationCovered=calendarCreationAvailable(m),calendarCount=value=>creationCovered&&covered?num(value):'—';
  const created=[...chains.values()].filter(e=>inPeriod(e.bookingCreatedAt));
  const scheduled=generic.filter(e=>e.isCurrentBooking&&e.status==='active'&&inPeriod(e.startAt));
  const upcoming=generic.filter(e=>e.isCurrentBooking&&e.status==='active'&&new Date(e.startAt)>new Date(m.snapshotAt));
  const rows=generic.filter(e=>inPeriod(e.startAt)||inPeriod(e.bookingCreatedAt));
  const proofs=(m.verifiedLinks||[]).filter(e=>inPeriod(e.bookingCreatedAt)||inPeriod(e.scheduledStartAt));
  let html=heading('Calendly booking evidence',`Charles’s calendar · collected ${shortTimestamp(m.snapshotAt)}. These counts follow the reporting dates; CRM owner/pipeline filters do not apply.`);
  html+=coverageBanner(`<strong>Bookings are not held meetings.</strong> Interviews are excluded. Generic 30-minute appointments remain commercially unclassified. Reschedules count once as a booking chain; original and replacement event records remain visible. Returned event-start window: ${esc(range(m.coverage))} (end exclusive). ${!creationCovered?'This selection is not fully covered by complete days before the actual calendar collection. Period booking counts are unavailable; future event-start coverage does not establish later bookings or attendance.':!covered?'The selection is outside the retrieved event-start window; period counts are unavailable.':partial?'The selection is partially covered; counts describe only the retrieved event window.':''}`,false);
  html+=kpis([[calendarCount(created.length),'Booking chains created','Within the retrieved event-start coverage'],[calendarCount(scheduled.length),'Active appointments scheduled','Start date in selection · not attendance'],[num(upcoming.length),'Upcoming appointments','At calendar collection · may now be past'],[num(confirmedHeldCalls().length||null),'Confirmed held linked calls','Owner-confirmed occurrence dates · bounded set']]);
  html+=table('crm-booking-matches','Corroborated lead bookings',proofs,[{key:'company',label:'Lead company'},{key:'ownerQualification',label:'Owner qualification',render:badge},{key:'bookingCreatedAt',label:'Booked',render:shortTimestamp},{key:'scheduledStartAt',label:'Scheduled',render:shortTimestamp},{key:'dealId',label:'CRM deal',render:v=>link(`https://centripetaladvisors.pipedrive.com/deal/${encodeURIComponent(v)}`,`Deal ${v}`)},{key:'heldStatus',label:'Attendance'}],'Exact invitee-name and email matches corroborate CRM identity. The owner confirms both linked calls were held. New inbox evidence conflicts with the Venus October 15 booking: an October 16 reschedule was accepted, so its exact held day remains unresolved. Qualification follows the latest explicit owner decision. Dates use Mountain time.');
  html+=`<details class="activity-review-details"><summary>Calendar records and coverage</summary>${table('crm-calendar-events','Calendar event register',rows,[{key:'name',label:'Event type'},{key:'bookingCreatedAt',label:'Original chain booked',render:shortTimestamp},{key:'startAt',label:'Scheduled start',render:shortTimestamp},{key:'status',label:'Calendar status'},{key:'isRescheduleReplacement',label:'Replacement',render:v=>v?'Yes':'No'},{key:'commercialClassification',label:'Commercial classification'},{key:'heldStatus',label:'Attendance'}],'Generic meeting types only; canceled originals and rescheduled replacements are separate event records. Counts above deduplicate the booking chain. Active is a calendar status, not proof of attendance.')}${panel('Calendar measurement limits',notes(m.notes))}</details>`;
  return html+recordingEvidenceReview();
}

